//! Diagnostic: time one drawn ecology world, 16 ticks, individual mode.
//! Built once against the core as committed and once against a local patch;
//! the final state hash must match, only the time may differ.
use isocosm::{Execution, Founding, Session};
use std::time::Instant;

fn main() {
    let seed: u64 = std::env::args().nth(1).expect("seed").parse().expect("integer seed");
    let founding = Founding {
        seed,
        sites: 256,
        population: 1024,
        lineages: 8,
        cohort_size: 32,
        ecology: true,
        ..Founding::default()
    };
    let mut session = Session::new(founding.generate().unwrap(), Execution::Individuals).unwrap();
    let mut ticks = Vec::new();
    let mut evaluations = 0;
    for _ in 0..16 {
        let t = Instant::now();
        evaluations += session.advance(1).unwrap().evaluations;
        ticks.push(t.elapsed().as_micros() as u64);
    }
    let mean = ticks.iter().sum::<u64>() / ticks.len() as u64;
    println!(
        "{{\"seed\":{seed},\"mean_tick_micros\":{mean},\"evaluations\":{evaluations},\"tick_micros\":{ticks:?},\"state_hash\":\"{}\"}}",
        session.sim.state_hash()
    );
}
